&lt;table CLASS=&quot;tablo col1centre&quot;&gt;&lt;caption&gt;Propri&#233;t&#233;s sp&#233;ciales d’arme&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Propri&#233;t&#233; sp&#233;ciale d’arme +1&lt;/td&gt;&lt;td&gt;Prix de base&lt;sup&gt;&lt;a class=&quot;internallink&quot; href=&quot;#ARMC1&quot; title=&quot;1&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Projectile&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Projectile fant&#244;me&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Pr&#233;hensile&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Pr&#233;hensile&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Chante-sang&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Chante-sang&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Diversion&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;De diversion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Riposte&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;De riposte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#D&#233;concertante&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;D&#233;concertante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Flamboyante&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Flamboyante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Fortuite&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Fortuite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Inspir&#233;e&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Inspir&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Querelleuse&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Querelleuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Sacr&#233;e&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Sacr&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Traque-esprits&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Traque-esprits&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Traque-sang&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Traque-sang&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Voleuse de destin&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Voleuse de destin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +1&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Propri&#233;t&#233; sp&#233;ciale d’arme +2&lt;/td&gt;&lt;td&gt;Prix de base&lt;sup&gt;&lt;a class=&quot;internallink&quot; href=&quot;#ARMC1&quot; title=&quot;1&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp%20objetsmagiques%20armes%20MCA.ashx#D’exclusion&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;D&#39;exclusion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+3 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Sournoise&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Sournoise&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#De diversion sup&#233;rieure&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;De diversion sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +2&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Propri&#233;t&#233; sp&#233;ciale d’arme +3&lt;/td&gt;&lt;td&gt;Prix de base&lt;sup&gt;&lt;a class=&quot;internallink&quot; href=&quot;#ARMC1&quot; title=&quot;1&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#&#201;puisante&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;&#201;puisante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Flamboyante sup&#233;rieure&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Flamboyante sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +3&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt titre&quot;&gt;&lt;td&gt;Propri&#233;t&#233; sp&#233;ciale d’arme +5&lt;/td&gt;&lt;td&gt;Prix de base&lt;sup&gt;&lt;a class=&quot;internallink&quot; href=&quot;#ARMC1&quot; title=&quot;1&quot;&gt;1&lt;/a&gt;&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp-Objetsmagiques-Armes-Mca.html#Volante&quot; title=&quot;Armes - Manuel des Joueurs R&#232;gles Avanc&#233;es&quot;&gt;Volante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;bonus +5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td COLSPAN=5&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ARMC1&quot; href=&quot;#ARMC1&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt; (1) Ajoutez le bonus d’alt&#233;ration de l’arme pour d&#233;terminer le prix total.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Chante-sang&quot; href=&quot;#Chante-sang&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Chante-sang&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Emplacement&lt;/b&gt; aucun &lt;b&gt;NLS&lt;/b&gt; 6 &lt;b&gt;Poids&lt;/b&gt; — &lt;br /&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;transmutation&lt;/a&gt; mod&#233;r&#233;e
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Cette propri&#233;t&#233; sp&#233;ciale d’arme ne peut &#234;tre appliqu&#233;e qu’aux armes
de corps &#224; corps tranchantes ou perforantes. Lorsque le personnage
profite des avantages d’une repr&#233;sentation de chant de rage (que ce
soit le sien ou celui d’un alli&#233;), cette arme gagne la propri&#233;t&#233; sp&#233;ciale
d’arme ac&#233;r&#233;e. Si le personnage confirme un coup critique alors qu’il
est sous les effets d’un chant de rage, il gagne 1d10 points de vie temporaires
qui durent jusqu’&#224; ce qu’ils soient r&#233;duits &#224; 0 ou que le chant
se termine (ce qui advient en premier). Si le multiplicateur critique de
l’arme est de &#215;3, ajoutez 2d10 points de vie temporaires &#224; la place ;
si le multiplicateur critique est de &#215;4, ajoutez 3d10 points de vie temporaires
&#224; la place. Lorsque son pouvoir est actif, l’arme vibre et &#233;met
un bourdonnement &#224; peine audible qui se mue en un cri per&#231;ant de
triomphe quand elle confirme un coup critique.
&lt;div class=&quot;box&quot;&gt;Fabrication&lt;/div&gt;
&lt;b&gt;Co&#251;t&lt;/b&gt; bonus +1
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et d’armures magiques&lt;/a&gt;, aff&#251;tage, le cr&#233;ateur doit
poss&#233;der le pouvoir de classe chant de rage, &lt;b&gt;Prix&lt;/b&gt; Bonus +1
&lt;/div&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;D’exclusion&quot; href=&quot;#D’exclusion&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;D&#39;exclusion&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Prix&lt;/b&gt; +3 750 po
&lt;b&gt;Emplacement&lt;/b&gt; aucun &lt;b&gt;NLS&lt;/b&gt; 1 &lt;b&gt;Poids&lt;/b&gt; —&lt;br /&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Necromancie.html&quot; title=&quot;N&#233;cromancie&quot;&gt;n&#233;cromancie&lt;/a&gt; faible
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Quand un personnage maniant une arme d’exclusion blesse une cr&#233;ature
avec cette arme, il peut d&#233;cider de ne pas affecter cette cr&#233;ature
avec les pouvoirs de canalisation d’&#233;nergie qu’il utilise au cours de la
minute suivante. Le nombre maximal de cibles qu’il peut exclure &#224; la
fois est &#233;gal &#224; son modificateur de Sagesse plus le bonus d’alt&#233;ration
de l’arme d’exclusion. Si le personnage qui manie une arme d’exclusion
touche une cr&#233;ature d&#233;passant ce nombre limite, il ne peut plus
exclure la cible qu’il exclut depuis le plus longtemps.
&lt;div class=&quot;box&quot;&gt;Fabrication&lt;/div&gt;&lt;b&gt;Co&#251;t&lt;/b&gt; 1 875 po
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et d’armures magiques&lt;/a&gt;, Canalisation s&#233;lective, sanctuaire
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Diversion&quot; href=&quot;#Diversion&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;De diversion&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Prix&lt;/b&gt;
Bonus+1
&lt;b&gt;Emplacement&lt;/b&gt; aucun &lt;b&gt;NLS&lt;/b&gt; 5 &lt;b&gt;Poids&lt;/b&gt; —&lt;br /&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;enchantement&lt;/a&gt; faible
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Les armes poss&#233;dant cette propri&#233;t&#233; sp&#233;ciale affectent les adversaires
touch&#233;s, qui ont alors du mal &#224; contr&#244;ler leur magie. Chaque fois
qu’une cr&#233;ature touch&#233;e par une arme de diversion doit r&#233;ussir un test
de concentration pour achever un sort ou utiliser un objet ou un pouvoir
sp&#233;cial, le DD de ce test est augment&#233; de 5. Cette diversion dure
1 minute. Une fois qu’une arme de diversion a affect&#233; une cr&#233;ature de
cette mani&#232;re, cette cr&#233;ature ne peut plus &#234;tre affect&#233;e par les effets
de diversion pendant 24 heures, m&#234;me si elle peut &#234;tre affect&#233;e par
un effet de diversion sup&#233;rieure.
&lt;div class=&quot;box&quot;&gt;Fabrication&lt;/div&gt;&lt;b&gt;Co&#251;t&lt;/b&gt; bonus +1
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et d’armures magiques&lt;/a&gt;, scrupuleAG
&lt;/div&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;De diversion sup&#233;rieure&quot; href=&quot;#De diversion sup&#233;rieure&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;De diversion sup&#233;rieure&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Prix&lt;/b&gt;
Bonus +2
&lt;b&gt;Emplacement&lt;/b&gt; aucun &lt;b&gt;NLS&lt;/b&gt; 8 &lt;b&gt;Poids&lt;/b&gt; —&lt;br /&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;enchantement&lt;/a&gt; mod&#233;r&#233;e
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Les armes poss&#233;dant cette propri&#233;t&#233; sp&#233;ciale affectent les adversaires
touch&#233;s, qui ont alors &#233;norm&#233;ment de mal &#224; contr&#244;ler leur magie.
Chaque fois qu’une cr&#233;ature touch&#233;e par une arme de diversion sup&#233;rieure
doit r&#233;ussir un test de concentration pour achever un sort ou
utiliser un objet ou un pouvoir sp&#233;cial, le DD de ce test est augment&#233;
de 10. Cette diversion dure 1 minute. Une fois qu’une arme de diversion
sup&#233;rieure a affect&#233; une cr&#233;ature de cette mani&#232;re, cette cr&#233;ature
ne peut plus &#234;tre affect&#233;e par les effets de diversion ou de diversion
sup&#233;rieure pendant 24 heures. Si une arme de diversion sup&#233;rieure
est utilis&#233;e contre une cr&#233;ature d&#233;j&#224; affect&#233;e par l’effet d’une arme de
diversion, les deux effets ne se cumulent pas : l’effet de diversion se
termine et la cr&#233;ature est affect&#233;e par l’effet de l’arme de diversion
sup&#233;rieure &#224; la place.
&lt;div class=&quot;box&quot;&gt;Fabrication&lt;/div&gt;&lt;b&gt;Co&#251;t&lt;/b&gt; bonus +2
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et d’armures magiques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Scrupule.html&quot; title=&quot;Scrupule&quot;&gt;scrupule&lt;/a&gt;&lt;sup&gt;AG&lt;/sup&gt;
&lt;/div&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Riposte&quot; href=&quot;#Riposte&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;De riposte&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - Classes avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Class Guide/Manuel des joueurs - Classes avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMCA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Prix&lt;/b&gt;
Bonus +1
&lt;b&gt;Emplacement&lt;/b&gt; aucun &lt;b&gt;NLS&lt;/b&gt; 7 &lt;b&gt;Poids&lt;/b&gt; —&lt;br /&gt;
&lt;b&gt;Aura&lt;/b&gt; enchantement mod&#233;r&#233;e
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Si le personnage qui manie une arme de riposte utilise l’exploit parade
et riposte opportune, le bonus d’alt&#233;ration de l’arme est augment&#233; de
4 (jusqu’&#224; un maximum de +5).
&lt;div class=&quot;box&quot;&gt;Fabrication&lt;/div&gt;&lt;b&gt;Co&#251;t&lt;/b&gt; bonus +1
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Darmes-Et-Armures-Magiques.html&quot; title=&quot;Cr&#233;ation d&amp;#39;armes et armures magiques&quot;&gt;Cr&#233;ation d’armes et d’armures magiques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Espoir.html&quot; title=&quot;Espoir&quot;&gt;espoir&lt;/a&gt;, le cr&#233;ateur doit
